FAILS = {
    "refused": lambda: urllib.error.URLError(ConnectionRefusedError()),
    "timeout": lambda: TimeoutError("timed out"),
    "connect-timeout": lambda: urllib.error.URLError(TimeoutError()),
    "reset": lambda: ConnectionResetError(),
    "disconnected": lambda: http.client.RemoteDisconnected("closed"),
    "dns": lambda: urllib.error.URLError(socket.gaierror()),
}


def _body(b) -> bytes:
    if isinstance(b, dict) and "raw" in b:
        return b["raw"].encode()
    if isinstance(b, dict) and "repeat" in b:
        return b.get("prefix", "").encode() + b["repeat"][0].encode() * b["repeat"][1] + b.get("suffix", "").encode()
    return json.dumps(b).encode()


class World:
    """Canned answers by "METHOD target". A route is {status, body}, {fail: kind}, a stream {status: 200, lines: [...],
    then?: reset} or a list of routes taken in turn (the last repeats). Records every request."""

    def __init__(self, routes, default=None):
        self.routes, self.default, self.seen, self.count = routes, default or {"status": 404, "body": {}}, [], {}

    def _route(self, req):
        key = f"{req.get_method()} {req.selector}"
        route = self.routes.get(key, self.default)
        if isinstance(route, list):
            i = self.count.get(key, 0)
            self.count[key] = i + 1
            route = route[min(i, len(route) - 1)]
        return route

    def _record(self, req):
        hdr = {k.lower(): v for k, v in req.header_items()}
        body = json.loads(req.data) if req.data else None
        rec = {"method": req.get_method(), "target": req.selector, "headers": {k: hdr[k] for k in KEEP if k in hdr}, "body": body}
        if body is not None:
            rec["headers"]["content-type"] = hdr.get("content-type")
        self.seen.append(rec)

    def __call__(self, req, timeout, ctx=None):
        self._record(req)
        route = self._route(req)
        if route.get("fail"):
            raise FAILS[route["fail"]]()
        return route["status"], _body(route["body"])

    def stream(self, req, timeout):
        self._record(req)
        route = self._route(req)
        if route.get("fail"):
            raise FAILS[route["fail"]]()
        if "lines" not in route:
            return route["status"], _body(route["body"])

        def lines():
            yield from (line.encode() for line in route["lines"])
            if route.get("then") == "reset":
                raise ConnectionResetError()
        return route["status"], lines()


