def _outcome(fn) -> dict:
    try:
        return {"result": fn()}
    except Denied as e:
        return {"denied": {"rule": e.rule, "message": e.message, "hint": e.hint}}
    except Exception as e:  # noqa: BLE001
        return {"error": {"class": type(e).__name__, "outcome_result": dispatch._error_result(e),
                          "agent_error": dispatch._backend_error(e)}}


def _norm(v):
    """Times a watch records are the wall clock's: written as "T"."""
    if isinstance(v, dict):
        return {k: ("T" if k == "at" else _norm(x)) for k, x in v.items()}
    if isinstance(v, list):
        return [_norm(x) for x in v]
    return v


