def run_case(name, tool, args, routes=None, *, sess=None, obo=False, git=True, glidepath=True, default=None,
             clock=None, go_error=None, go_extra=None, **extra):
    """Drive the Python handler for `tool` and record it. clock: (fake clock, sleep) for a watch."""
    world = World(routes or {}, default)
    sess = sess or Sess()
    gp = GlidepathAPI("http://gp.test/gp", TMP / "gp", on_behalf_of=obo, opener=world, stream_opener=world.stream) if glidepath else None
    g = GitHubPRs(TMP / "agent", broker_url="http://gh.test/b", api="https://api.github.test", opener=lambda req, t: world(req, t)) if git else None
    h = hangar_handlers(Backends(g, None, None, None, None, None, gp, None))
    if clock:
        t = [0.0]
        glidepath_live.watch.__defaults__ = (lambda: t[0], lambda d: t.__setitem__(0, t[0] + d))
    try:
        out = _outcome(lambda: h[tool](sess, args))
    finally:
        glidepath_live.watch.__defaults__ = (glidepath_live.time.monotonic, glidepath_live.time.sleep)
    if go_error:
        cls, msg = go_error
        extra["go"] = {"error": {"class": cls, "outcome_result": f"error:{cls}: {msg[:160]}", "agent_error": "backend error: " + msg[:360]},
                       "requests": world.seen + (go_extra or [])}
        extra["why"] = ("a write that was sent and not answered says it may have been made, and Go looks once (a GET) for the branch or the "
                        "pull request it would have made before saying so")
    if "result" in out and tool in TOOL_REGISTRY:
        # the receipt the outcome carries (dispatch._effect), which the Go dispatch must make of the same result
        out["effect"] = dispatch._effect(TOOL_REGISTRY[tool], args, out["result"])
    CASES.append({"name": name, "tool": tool, "args": args, "session": sess.as_dict(), "routes": routes or {}, "default": world.default,
                  "obo": obo, "git": git, "glidepath": glidepath, "clock": bool(clock), "requests": world.seen, **_norm(out), **extra})


def run_direct(name, method, args, routes=None, **extra):
    """Drive a GitHubPRs method that no tool calls yet (ensure_pr, find_pr: airframe.apply's, S5c)."""
    world = World(routes or {})
    g = GitHubPRs(TMP / "agent", broker_url="http://gh.test/b", api="https://api.github.test", opener=lambda req, t: world(req, t))
    out = _outcome(lambda: getattr(g, method)(**args))
    CASES.append({"name": name, "tool": "direct:" + method, "args": args, "session": Sess().as_dict(), "routes": routes or {},
                  "default": world.default, "obo": False, "git": True, "glidepath": False, "clock": False, "requests": world.seen,
                  **out, **extra})


def run_argo(name, app, project, objs, patch_status=200, *, who=None, patch_fail=None, namespaces=("argocd", "argocd-apps"), **extra):
    """argo.sync.lower over an Application the Kubernetes API serves (objs: path -> object), patched at the same server."""
    routes = {}
    for path, obj in objs.items():
        routes[f"GET /k{path}"] = {"status": 200, "body": obj}
    for ns in namespaces:
        for path in objs:
            pass
    patch_routes = {}
    if patch_fail:
        patch_routes["fail"] = patch_fail
    else:
        patch_routes.update(status=patch_status, body={})
    for path in {f"/apis/argoproj.io/v1alpha1/namespaces/{ns}/applications/{app}" for ns in namespaces}:
        routes[f"PATCH /k{path}"] = patch_routes
    world = World(routes)
    reader = KubeReader("https://k8s.test/k", TMP / "k", None, opener=world)
    syncer = ArgoSync(reader, tuple(namespaces), server="https://k8s.test/k", token_file=TMP / "k", ca_file=None, opener=world)
    argo = KubeArgo(reader, tuple(namespaces), syncer=syncer)
    h = hangar_handlers(Backends(None, argo, None, None, None, None, None, None))
    sess = Sess()
    # the handler builds who from the session; a case that wants another passes it through the session
    out = _outcome(lambda: h["argo.sync.lower"](sess, {"app": app, "project": project}))
    CASES.append({"name": name, "tool": "argo.sync.lower", "args": {"app": app, "project": project}, "session": sess.as_dict(),
                  "routes": routes, "default": world.default, "namespaces": list(namespaces), "requests": world.seen, **out, **extra})


