def go_denied(d, requests=None, why="Go refuses first, from its own scope check and its stricter validation"):
    return {"go": {"denied": d, "requests": requests or []}, "why": why}


def go_echo(v):
    r = repr(v)
    return (repr(v[:100]) + "...") if isinstance(v, str) and len(v) > 100 else r


